from typing import Generic, TypeVar, Union

T = TypeVar('T')

class Option(Generic[T]):
    """Base class for the Option type."""
    pass

class Some(Option[T]):
    """Option variant that contains a value."""
    def __init__(self, value: T):
        self.value = value

class Nothing(Option[T]):
    """Option variant that represents the absence of a value."""
    pass

def divide(numerator: float, denominator: float) -> Option[float]:
    """Safely divides two numbers returning an Option type."""
    if denominator == 0:
        return Nothing()
    return Some(numerator / denominator)

def print_option_result(result: Option[float]) -> None:
    """Prints the result of the division operation."""
    if isinstance(result, Some):
        print(f"Result: {result.value}")
    else:
        print("Error: Division by zero")

def main() -> None:
    """Main execution block for testing the safe division function."""
    test_cases = [(10, 2), (10, 0)]

    for a, b in test_cases:
        result = divide(a, b)
        print_option_result(result)

if __name__ == "__main__":
    main()

