import std/string (length, substring)

-- Helper function: check balance recursively with a counter
-- Uses index to iterate through string
func checkBalance(s: string, index: int, counter: int) -> bool =
  if index >= length(s) then
    counter == 0
  else
    let ch = substring(s, index, index + 1) in
    if ch == "(" then
      checkBalance(s, index + 1, counter + 1)
    else if ch == ")" then
      if counter > 0 then
        checkBalance(s, index + 1, counter - 1)
      else
        false
    else
      checkBalance(s, index + 1, counter)

-- Main function to check if parentheses are balanced
func isBalanced(s: string) -> bool =
  checkBalance(s, 0, 0)

export func main() -> () ! {IO} {
  let test1 = isBalanced("(())");
  let test2 = isBalanced("(()");
  let test3 = isBalanced("())()");
  let test4 = isBalanced("()(())");
  print(show(test1));
  print(show(test2));
  print(show(test3));
  print(show(test4))
}

