def isBalanced(s: str) -> bool:
    counter = 0
    for char in s:
        if char == '(':
            counter += 1
        elif char == ')':
            counter -= 1

        if counter < 0:
            return False

    return counter == 0


def main() -> None:
    test_strings = [
        "(())",
        "(()",
        "())()",
        "()(())"
    ]

    for s in test_strings:
        result = isBalanced(s)
        print(str(result).lower())


if __name__ == "__main__":
    main()

