import sys
from typing import Union, Optional

# To allow for deep recursion
sys.setrecursionlimit(2000)

class Leaf:
    def __init__(self, value: int):
        self.value = value

class Branch:
    def __init__(self, left: 'Tree', value: int, right: 'Tree'):
        self.left = left
        self.value = value
        self.right = right

Tree = Union[Branch, Leaf, None]

def treeSum(tree: Optional[Tree]) -> int:
    if tree is None:
        return 0
    if isinstance(tree, Leaf):
        return tree.value
    if isinstance(tree, Branch):
        return tree.value + treeSum(tree.left) + treeSum(tree.right)
    return 0

def main():
    # Creates this tree:
    #         5
    #        / \
    #       3   8
    #      / \   \
    #     1   4   10
    tree = Branch(
        left=Branch(
            left=Leaf(1),
            value=3,
            right=Leaf(4)
        ),
        value=5,
        right=Branch(
            left=None,
            value=8,
            right=Leaf(10)
        )
    )

    result = treeSum(tree)
    print(result)

if __name__ == "__main__":
    main()

