import sys
from pathlib import Path
from typing import List, Optional

def process_file_content(file_path: Path) -> List[str]:
    """
    Reads a file and returns a list of uppercase, non-empty lines.
    """
    try:
        with file_path.open(mode="r", encoding="utf-8") as file:
            return [line.strip().upper() for line in file if line.strip()]
    except FileNotFoundError:
        raise FileNotFoundError(f"The file at {file_path} was not found.")
    except PermissionError:
        raise PermissionError(f"Permission denied when accessing {file_path}.")

def main(arguments: Optional[List[str]] = None) -> None:
    """
    Main entry point for the script.
    """
    if arguments is None:
        arguments = sys.argv[1:]

    if not arguments:
        print("Usage: python script.py <filename>")
        sys.exit(1)

    input_path = Path(arguments[0])

    try:
        processed_lines = process_file_content(input_path)

        if not processed_lines:
            print(f"No valid content found in {input_path}.")
            return

        print(f"Processed {len(processed_lines)} lines from '{input_path.name}':")
        for i, line in enumerate(processed_lines, start=1):
            print(f"{i:02d}: {line}")

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

