import std/fs (readFile)
import std/json (decode, get, asString, asNumber, asArray)
import std/string (split)
import std/list (length)
import std/option (Option, Some, None)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: [Json]
}

pure func validateVersion(version: string) -> bool {
  length(split(version, ".")) == 3
}

pure func validatePort(port: int) -> bool {
  port >= 1024 && port <= 65535
}

pure func validateFeatures(features: [Json]) -> bool {
  length(features) > 0
}

func parseConfig(json: Json) -> Option[Config] {
  match get(json, "app_name") {
    Some(appNameJson) => match asString(appNameJson) {
      Some(appName) => match get(json, "version") {
        Some(versionJson) => match asString(versionJson) {
          Some(version) => match get(json, "port") {
            Some(portJson) => match asNumber(portJson) {
              Some(portFloat) => match get(json, "features") {
                Some(featuresJson) => match asArray(featuresJson) {
                  Some(features) => {
                    let port = floatToInt(portFloat);
                    if validateVersion(version) && validatePort(port) && validateFeatures(features) then
                      Some({app_name: appName, version: version, port: port, features: features})
                    else
                      None
                  },
                  None => None
                },
                None => None
              },
              None => None
            },
            None => None
          },
          None => None
        },
        None => None
      },
      None => None
    },
    None => None
  }
}

export func main() -> () ! {IO, FS} {
  let content = readFile("app_config.json");
  match decode(content) {
    Ok(json) => {
      match parseConfig(json) {
        Some(config) => {
          print("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(length(config.features)) ++ " features")
        },
        None => print("Invalid configuration")
      }
    },
    Err(msg) => print("JSON parse error: " ++ msg)
  }
}

module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (split, trim, stringToInt, find)
import std/list (map, filter, length)
import std/json (encode, ja, jo, kv, js, jnum)
import std/option (isSome)

type User = {
  name: string,
  age: int,
  email: string
}

func parseRow(row: string) -> Option[User] {
    let parts = split(row, ",");
    if length(parts) == 3 then {
        let name = fromSome(get(parts, 0));
        let ageStr = fromSome(get(parts, 1));
        let email = fromSome(get(parts, 2));
        match stringToInt(ageStr) {
            Some(age) => Some({ name: name, age: age, email: email }),
            None => None
        }
    } else {
        None
    }
}

func validateUser(user: User) -> bool {
  user.age > 0 && isSome(find(user.email, " @"))
}

func userToJson(user: User) -> Json {
  jo([
    kv("name", js(user.name)),
    kv("age", jnum(toFloat(user.age))),
    kv("email", js(user.email))
  ])
}

export func main() -> () ! {IO, FS} {
  let content = readFile("users.csv");
  let lines = split(content, "\n");

  let dataLines = match lines {
    _ :: rest => rest,
    [] => []
  };

  let nonEmptyLines = filter(
    \line. trim(line) != "", dataLines
  );

  let maybeUsers = map(parseRow, nonEmptyLines);
  let validUsers = filter(isSome, maybeUsers);
  let users = map(fromSome, validUsers);

  let validatedUsers = filter(validateUser, users);

  let jsonObjects = map(userToJson, validatedUsers);
  let jsonArray = ja(jsonObjects);
  let jsonString = encode(jsonArray);

  let _ = writeFile("users.json", jsonString);

  print("Converted " ++ show(length(validatedUsers)) ++ " valid rows to users.json")
}

func getRec[a](list: [a], index: int) -> Option[a] {

    match list {

      [] => None,

      h :: t => if index == 0 then Some(h) else getRec(t, index - 1)

    }

}



func get[a](list: [a], index: int) -> Option[a] {

  if index < 0 then None else getRec(list, index)

}

