import csv
import json
from pathlib import Path
from typing import Dict, Any, List

def create_input_file(file_path: Path) -> None:
    content = (
        "name,age,email\n"
        "Alice,30,alice@example.com\n"
        "Bob,25,bob@example.com\n"
        "Carol,35,carol@example.com"
    )
    file_path.write_text(content, encoding="utf-8")

def is_valid(row: Dict[str, str]) -> bool:
    try:
        age_val = row.get("age", "")
        if not age_val:
            return False
        age = int(age_val)
        if age <= 0:
            return False
    except ValueError:
        return False

    email = row.get("email", "")
    if "@" not in email:
        return False

    return True

def process_conversion(csv_path: Path, json_path: Path) -> int:
    valid_data: List[Dict[str, Any]] = []

    with csv_path.open(mode="r", encoding="utf-8", newline="") as csv_file:
        reader = csv.DictReader(csv_file)
        for row in reader:
            if is_valid(row):
                valid_data.append({
                    "name": row["name"],
                    "age": int(row["age"]),
                    "email": row["email"]
                })

    with json_path.open(mode="w", encoding="utf-8") as json_file:
        json.dump(valid_data, json_file, indent=2)

    return len(valid_data)

def main() -> None:
    csv_file = Path("users.csv")
    json_file = Path("users.json")

    create_input_file(csv_file)
    count = process_conversion(csv_file, json_file)

    print(f"Converted {count} valid rows to {json_file}")

if __name__ == "__main__":
    main()

