from typing import Union


class Ok:
    def __init__(self, value: int):
        self.value = value


class Err:
    def __init__(self, message: str):
        self.message = message


Result = Union[Ok, Err]


def parse_int(s: str) -> Result:
    try:
        value = int(s)
        return Ok(value)
    except ValueError:
        return Err("Invalid integer")


def divide_safe(a: int, b: int) -> Result:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)


def chain_operations(s: str, divisor: int) -> Result:
    parse_result = parse_int(s)

    if isinstance(parse_result, Err):
        return parse_result

    value = parse_result.value
    return divide_safe(value, divisor)


def format_result(result: Result) -> str:
    if isinstance(result, Ok):
        return f"Result: {result.value}"
    else:
        return f"Error: {result.message}"


def main():
    test_cases = [
        ("10", 2),
        ("10", 0),
        ("abc", 2),
    ]

    for input_str, divisor in test_cases:
        result = chain_operations(input_str, divisor)
        print(format_result(result))


if __name__ == "__main__":
    main()

