  }

-- Enqueue: add to end of list
func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    h :: rest => h :: enqueue(x, rest)
  }

-- Get neighbors of a node from adjacency list
func getNeighbors(node: int, graph: [{node: int, neighbors: [int]}]) -> [int] =
  match graph {
    [] => [],
    {node: n, neighbors: nbs} :: rest =>
      if n == node then nbs else getNeighbors(node, rest)
  }

-- Add all elements from source list to end of queue
func enqueueList(source: [int], queue: [int]) -> [int] =
  match source {
    [] => queue,
    h :: rest => enqueueList(rest, enqueue(h, queue))
  }

-- BFS implementation with accumulator approach
func bfsHelper(queue: [int], visited: [int], graph: [{node: int, neighbors: [int]}]) -> [int] =
