from __future__ import annotations
from dataclasses import dataclass
from typing import Union

@dataclass
class TVar:
    name: str

@dataclass
class TLam:
    var: str
    body: 'Term'

@dataclass
class TApp:
    func: 'Term'
    arg: 'Term'

Term = Union[TVar, TLam, TApp]

def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        return replacement if term.name == var else term
    if isinstance(term, TLam):
        if term.var == var:
            return term
        return TLam(term.var, subst(term.body, var, replacement))
    if isinstance(term, TApp):
        return TApp(subst(term.func, var, replacement), subst(term.arg, var, replacement))
    return term

def eval(term: Term) -> Term:
    if isinstance(term, TVar):
        return term
    if isinstance(term, TLam):
        return term
    if isinstance(term, TApp):
        func = eval(term.func)
        arg = eval(term.arg)
        if isinstance(func, TLam):
            return eval(subst(func.body, func.var, arg))
        return TApp(func, arg)
    return term

def main() -> None:
    expr = TApp(
        TApp(
            TLam("x", TLam("y", TVar("x"))),
            TVar("1")
        ),
        TVar("2")
    )
    result = eval(expr)
    if isinstance(result, TVar):
        print(result.name)
    else:
        print(result)

if __name__ == "__main__":
    main()

