import std/io (println)
import std/fs (readFile)
import std/string (split, trim)
import std/list (length, filter, foldl, map)

-- Parse a single log line and extract level and optional user
type ParsedLog = {level: string, user: string}

-- Get last element from list (helper for extractUser)
func getLast(xs: [string]) -> string =
  match xs {
    [] => "",
    [x] => x,
    _ :: rest => getLast(rest)
  }

-- Extract text after the last colon (user name)
func extractUser(message: string) -> string =
  let parts = split(":", message) in
  trim(getLast(parts))

-- Parse a log line: "2024-10-29 10:00:00 INFO User logged in: alice"
func parseLine(line: string) -> ParsedLog =
  let parts = split(" ", trim(line)) in
  let level = match parts {
    _ :: _ :: levelPart :: _ => levelPart,
    _ => ""
  } in
  let message = trim(line) in
  let user = if level == "INFO" || level == "ERROR" || level == "WARNING" then
    extractUser(message)
  else
    "" in
  {level: level, user: user}

-- Count occurrences in a list
func countMatches(pred: string -> bool, xs: [string]) -> int =
  match xs {
    [] => 0,
    x :: rest => if pred(x) then 1 + countMatches(pred, rest) else countMatches(pred, rest)
  }

-- Remove duplicates from list (simple version)
func removeDuplicates(xs: [string]) -> [string] =
  match xs {
    [] => [],
    x :: rest =>
      let filtered = filter(\y. y != x, rest) in
      x :: removeDuplicates(filtered)
  }

-- Simple insertion sort
func sortStrings(xs: [string]) -> [string] =
  match xs {
    [] => [],
    [x] => [x],
    x :: rest =>
      let sorted_rest = sortStrings(rest) in
      insertIntoSorted(x, sorted_rest)
  }

func insertIntoSorted(x: string, sorted: [string]) -> [string] =
  match sorted {
    [] => [x],
    h :: t => if x <= h then x :: sorted else h :: insertIntoSorted(x, t)
  }

export func main() -> () ! {IO, FS} {
  let content = readFile("benchmark/app.log");
  let lines = split("\n", content);
  let nonEmpty = filter(\l. trim(l) != "", lines);
  let parsed = map(parseLine, nonEmpty);
  let totalCount = length(nonEmpty);
  let infoCount = countMatches(\p. p == "INFO", map(\log. log.level, parsed));
  let errorCount = countMatches(\p. p == "ERROR", map(\log. log.level, parsed));
  let warningCount = countMatches(\p. p == "WARNING", map(\log. log.level, parsed));
  let infoPct = if totalCount > 0 then (infoCount * 100) / totalCount else 0;
  let errorPct = if totalCount > 0 then (errorCount * 100) / totalCount else 0;
  let warningPct = if totalCount > 0 then (warningCount * 100) / totalCount else 0;
  let users = map(\log. log.user, parsed);
  let nonEmptyUsers = filter(\u. u != "", users);
  let uniqueUsers = removeDuplicates(nonEmptyUsers);
  let sortedUsers = sortStrings(uniqueUsers);
  let userStr = foldl(\acc. \u. if acc == "" then u else acc ++ ", " ++ u, "", sortedUsers);
  println("Total log entries: " ++ show(totalCount));
  println("INFO: " ++ show(infoCount) ++ " (" ++ show(infoPct) ++ "%)");
  println("ERROR: " ++ show(errorCount) ++ " (" ++ show(errorPct) ++ "%)");
  println("WARNING: " ++ show(warningCount) ++ " (" ++ show(warningPct) ++ "%)");
  println("Unique users: " ++ userStr)
}

