from __future__ import annotations
from dataclasses import dataclass
from typing import Union, List, Tuple


@dataclass
class Num:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: Expr
    right: Expr


@dataclass
class Mul:
    left: Expr
    right: Expr


@dataclass
class Let:
    name: str
    value: Expr
    body: Expr


Expr = Union[Num, Var, Add, Mul, Let]
Env = List[Tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for n, v in reversed(env):
        if n == name:
            return v
    raise NameError(f"Variable '{name}' is not defined")


def eval_expr(expr: Expr, env: Env) -> int:
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        return eval_expr(expr.left, env) + eval_expr(expr.right, env)
    elif isinstance(expr, Mul):
        return eval_expr(expr.left, env) * eval_expr(expr.right, env)
    elif isinstance(expr, Let):
        val = eval_expr(expr.value, env)
        # Create a new environment scope by appending the new binding
        new_env = env + [(expr.name, val)]
        return eval_expr(expr.body, new_env)
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")


def main() -> None:
    # let x = 5 in
    #   let y = x + 3 in
    #     x * y
    program = Let(
        "x",
        Num(5),
        Let(
            "y",
            Add(Var("x"), Num(3)),
            Mul(Var("x"), Var("y"))
        )
    )

    result = eval_expr(program, [])
    print(result)


