from typing import TypeVar, Generic, Callable, List

T = TypeVar("T")
U = TypeVar("U")

class Option(Generic[T]):
    pass

class Some(Option[T]):
    __slots__ = ("value",)
    def __init__(self, value: T):
        self.value = value

    def __repr__(self) -> str:
        return f"Some({self.value!r})"

class Nothing(Option[T]):
    __slots__ = ()
    def __repr__(self) -> str:
        return "Nothing"

def findFirst(predicate: Callable[[T], bool], items: List[T]) -> Option[T]:
    for item in items:
        if predicate(item):
            return Some(item)
    return Nothing()

def mapOption(fn: Callable[[T], U], option: Option[T]) -> Option[U]:
    if isinstance(option, Some):
        return Some(fn(option.value))
    return Nothing()

def main() -> None:
    is_even = lambda n: n % 2 == 0
    double = lambda n: n * 2

    # Test case 1
    list1 = [1, 2, 3, 4, 5]
    result1 = mapOption(double, findFirst(is_even, list1))
