from __future__ import annotations
from dataclasses import dataclass
from enum import Enum, auto
from typing import Optional, List

class Color(Enum):
    RED = auto()
    BLACK = auto()

@dataclass
class Node:
    color: Color
    left: Optional[Node]
    value: int
    right: Optional[Node]
    __match_args__ = ("color", "left", "value", "right")

def balance(color: Color, left: Optional[Node], value: int, right: Optional[Node]) -> Node:
    match (color, left, value, right):
        case (Color.BLACK, Node(Color.RED, Node(Color.RED, a, x, b), y, c), z, d):
            return Node(Color.RED, Node(Color.BLACK, a, x, b), y, Node(Color.BLACK, c, z, d))
        case (Color.BLACK, Node(Color.RED, a, x, Node(Color.RED, b, y, c)), z, d):
            return Node(Color.RED, Node(Color.BLACK, a, x, b), y, Node(Color.BLACK, c, z, d))
        case (Color.BLACK, a, x, Node(Color.RED, Node(Color.RED, b, y, c), z, d)):
            return Node(Color.RED, Node(Color.BLACK, a, x, b), y, Node(Color.BLACK, c, z, d))
        case (Color.BLACK, a, x, Node(Color.RED, b, y, Node(Color.RED, c, z, d))):
            return Node(Color.RED, Node(Color.BLACK, a, x, b), y, Node(Color.BLACK, c, z, d))
        case _:
            return Node(color, left, value, right)

def insert(x: int, tree: Optional[Node]) -> Node:
    def ins(t: Optional[Node]) -> Node:
        if t is None:
            return Node(Color.RED, None, x, None)
        if x < t.value:
            return balance(t.color, ins(t.left), t.value, t.right)
        elif x > t.value:
            return balance(t.color, t.left, t.value, ins(t.right))
        else:
            return t

    result = ins(tree)
    return Node(Color.BLACK, result.left, result.value, result.right)

def inorder(tree: Optional[Node]) -> List[int]:
    if tree is None:
        return []
    return inorder(tree.left) + [tree.value] + inorder(tree.right)

def main():
    values = [7, 3, 18, 10, 22, 8, 11, 26]
    root = None
    for v in values:
        root = insert(v, root)

    print(inorder(root))

if __name__ == "__main__":
    main()

