func diff(expr: Expr, var: string) -> Expr =
  match expr {
    Const(_) => Const(0),
    Var(v) => if v == var then Const(1) else Const(0),
    Add(f, g) => Add(diff(f, var), diff(g, var)),
    Mul(f, g) => Add(Mul(f, diff(g, var)), Mul(g, diff(f, var)))
  }

func simplify(expr: Expr) -> Expr =
  match expr {
    Const(_) => expr,
    Var(_) => expr,
    Add(f, g) => {
      let sf = simplify(f);
      let sg = simplify(g);
      match (sf, sg) {
        (Const(0), e) => e,
        (e, Const(0)) => e,
        (Const(a), Const(b)) => Const(a + b),
        _ => Add(sf, sg)
      }
    },
    Mul(f, g) => {
      let sf = simplify(f);
