      match (sf, sg) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), e) => e,
        (e, Const(1)) => e,
        (Const(a), Const(b)) => Const(a * b),
        _ => Mul(sf, sg)
