from __future__ import annotations
from dataclasses import dataclass
from typing import Union


@dataclass
class Const:
    val: int

    def __str__(self) -> str:
        return f"Const({self.val})"


@dataclass
class Var:
    name: str

    def __str__(self) -> str:
        return f"Var({self.name})"


@dataclass
class Add:
    left: Expr
    right: Expr

    def __str__(self) -> str:
        return f"Add({self.left}, {self.right})"


@dataclass
class Mul:
    left: Expr
    right: Expr

    def __str__(self) -> str:
        return f"Mul({self.left}, {self.right})"


Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    if isinstance(expr, Const):
        return Const(0)
    if isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    if isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    if isinstance(expr, Mul):
        # Product rule: d/dx(f * g) = f * d/dx(g) + g * d/dx(f)
        return Add(
            Mul(expr.left, diff(expr.right, var)),
            Mul(expr.right, diff(expr.left, var))
        )
    raise TypeError("Unknown expression type")


def simplify(expr: Expr) -> Expr:
    if isinstance(expr, Add):
        l = simplify(expr.left)
        r = simplify(expr.right)
        if isinstance(l, Const) and l.val == 0:
            return r
        if isinstance(r, Const) and r.val == 0:
            return l
        return Add(l, r)

    if isinstance(expr, Mul):
        l = simplify(expr.left)
        r = simplify(expr.right)
        if isinstance(l, Const):
            if l.val == 0:
                return Const(0)
            if l.val == 1:
                return r
        if isinstance(r, Const):
            if r.val == 0:
                return Const(0)
            if r.val == 1:
                return l
        return Mul(l, r)

    return expr


