module benchmark/solution

import std/io (println)

-- Type ADT
type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

-- Substitution: list of (varName, Type) pairs
type Binding = {var: string, typ: Type}

-- Check if two strings are equal (builtin comparison for strings)
pure func strEq(s1: string, s2: string) -> bool =
  s1 == s2

-- Unify two types
pure func unify(t1: Type, t2: Type) -> [Binding] =
  match t1 {
    TInt => match t2 {
      TInt => [],
      _ => []
    },
    TBool => match t2 {
      TBool => [],
      _ => []
    },
    TVar(a) => match t2 {
      TVar(b) => if strEq(a, b) then [] else [{var: a, typ: TVar(b)}],
      _ => [{var: a, typ: t2}]
    },
    TFunc(a1, r1) => match t2 {
      TFunc(a2, r2) => unifyHelper(a1, a2, r1, r2),
      _ => []
    }
  }

-- Helper to unify function types
pure func unifyHelper(a1: Type, a2: Type, r1: Type, r2: Type) -> [Binding] =
  match a1 {
    TInt => match a2 {
      TInt => unifyBase(r1, r2),
      _ => []
    },
    TBool => match a2 {
      TBool => unifyBase(r1, r2),
      _ => []
    },
    TVar(varname) => match a2 {
      TVar(varname2) => if strEq(varname, varname2) then unifyBase(r1, r2) else {
        let s1 = [{var: varname, typ: TVar(varname2)}];
        concatenateSubst(s1, unifyBase(r1, r2))
      },
      _ => {
        let s1 = [{var: varname, typ: a2}];
        concatenateSubst(s1, unifyBase(r1, r2))
      }
    },
    _ => []
  }

-- Base unification for simple cases
pure func unifyBase(t1: Type, t2: Type) -> [Binding] =
  match t1 {
    TInt => match t2 {
      TInt => [],
      _ => []
    },
    TBool => match t2 {
      TBool => [],
      _ => []
    },
    TVar(a) => match t2 {
      TVar(b) => if strEq(a, b) then [] else [{var: a, typ: TVar(b)}],
      _ => [{var: a, typ: t2}]
    },
    TFunc(_, _) => []
  }

-- Concatenate two substitutions
pure func concatenateSubst(s1: [Binding], s2: [Binding]) -> [Binding] =
  match s1 {
    [] => s2,
    x :: rest => x :: concatenateSubst(rest, s2)
  }

-- Format a type for display
pure func formatType(t: Type) -> string =
  match t {
    TVar(name) => name,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, res) => "TFunc(" ++ formatType(arg) ++ ", " ++ formatType(res) ++ ")"
  }

-- Main entry point
export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  let subst = unify(t1, t2);
  printSubstitution(subst)
}

-- Print substitution
func printSubstitution(subst: [Binding]) -> () ! {IO} =
  match subst {
    [] => println("No unification"),
    x :: rest => {
      let msg = x.var ++ " = " ++ formatType(x.typ);
      let _ = println(msg);
      printSubstitution(rest)
    }
  }

